def _build_kv_connector_meta(
    self, connector: KVConnectorBase_V1, scheduler_output: SchedulerOutput
) -> KVConnectorMetadata:
    return connector.build_connector_meta(scheduler_output)

def _try_promote_blocked_waiting_request(self, request: Request) -> bool:
    """
    Try to promote a blocked waiting request back to schedulable states.
    """
    if request.status == RequestStatus.WAITING_FOR_REMOTE_KVS:
        # finished_recving_kv_req_ids is populated during
        # update_from_output(), based on worker-side connector signals
        # in KVConnectorOutput.finished_recving
        if request.request_id not in self.finished_recving_kv_req_ids:
            return False
        self._update_waiting_for_remote_kv(request)
        if request.num_preemptions:
            request.status = RequestStatus.PREEMPTED
        else:
            request.status = RequestStatus.WAITING
        return True

def kv_connector_no_forward(
    scheduler_output: "SchedulerOutput", vllm_config: VllmConfig
) -> ModelRunnerOutput:
    # KV send/recv even if no work to do.
    with (
        set_forward_context(None, vllm_config),
        KVConnectorModelRunnerMixin._get_kv_connector_output(
            scheduler_output, wait_for_save=False
        ) as kv_connector_output,
    ):
        pass

    return ModelRunnerOutput.with_kv_conn_output_only(kv_connector_output)

@staticmethod
def maybe_get_kv_connector_output(
    scheduler_output: "SchedulerOutput",
    defer_finalize: bool = False,
) -> AbstractContextManager[KVConnectorOutput | None]:
    return (
        KVConnectorModelRunnerMixin._get_kv_connector_output(
            scheduler_output, defer_finalize=defer_finalize
        )
        if has_kv_transfer_group()
        else nullcontext()
    )

@staticmethod
def finalize_kv_connector() -> None:
    """Finalize the KV connector: wait_for_save and clear metadata.

    Call after draft model forward when defer_finalize=True was used.
    """
    if has_kv_transfer_group():
        kv_connector = get_kv_transfer_group()
        kv_connector.wait_for_save()
        kv_connector.clear_connector_metadata()

    def extract_kv_from_layer(
        layer: torch.Tensor,
        slot_mapping: torch.Tensor,
    ) -> torch.Tensor:
        """Extract the KV cache from the layer.

        Assume the shape of the layer is (num_pages, page_size, xxx)
        for MLA, and (num_pages, 2, page_size, xxx) otherwise.
        """
        if isinstance(attn_metadata, MLACommonMetadata):
            num_pages, page_size = layer.shape[0], layer.shape[1]
            return layer.reshape(num_pages * page_size, -1)[slot_mapping, ...]
        block_idxs = slot_mapping // self._block_size
        offsets = slot_mapping % self._block_size
        return layer[block_idxs, :, offsets]

    connector_metadata = self._get_connector_metadata()
    assert isinstance(connector_metadata, ExampleConnectorMetadata)
    for request in connector_metadata.requests:
        if request.is_store:
            filename = self._generate_filename_debug(
                layer_name, request.token_ids, request.mm_hashes
            )
            kv_cache = extract_kv_from_layer(kv_layer, request.slot_mapping)
            tensors = {"kv_cache": kv_cache.detach().cpu()}
            safetensors.torch.save_file(tensors, filename)

